// aisha_test_mcp_server returned { test_id, payload: {transport, endpoint_url,
// auth_kind, auth_env_var, probe_method, ...} }. We do the HTTP probe here
// (n8n is the runtime; SSRF concerns are minimal because targets come from
// our own mcp_server_registry — operator-curated, not user input).
//
// Note: stdio transport excluded by get_mcp_servers_due_probe upstream, so
// here we handle http + sse + websocket. Websocket probes are emulated as
// HTTP GET (just connectivity, not protocol-level handshake).

const auditResp = $input.first().json;
const payload = auditResp.payload || {};
const originalMcp = $('Split Per MCP').first().json;

const probeMethod = payload.probe_method || 'tools/list';
const transport = payload.transport || originalMcp.transport;
const endpointUrl = payload.endpoint_url || originalMcp.endpoint_url;
const authEnvVar = payload.auth_env_var || originalMcp.auth_env_var;

if (!endpointUrl) {
  return [
    {
      json: {
        slug: originalMcp.slug,
        skip: true,
        ok: false,
        latency_ms: 0,
        error: 'no endpoint_url',
        supported_methods: [],
        sample_response_excerpt: null,
      },
    },
  ];
}

const probeStartedAt = Date.now();
const token = authEnvVar ? (process.env[authEnvVar] || '') : '';

let ok = false;
let latencyMs = 0;
let supportedMethods = [];
let sampleResponseExcerpt = null;
let error = null;

try {
  // JSON-RPC 2.0 over HTTP — standard MCP transport. tools/list returns
  // { jsonrpc, id, result: { tools: [{name, description, ...}, ...] } }.
  const body = {
    jsonrpc: '2.0',
    id: auditResp.test_id || 'probe-1',
    method: probeMethod,
    params: {},
  };

  const headers = { 'Content-Type': 'application/json' };
  if (token) headers.Authorization = `Bearer ${token}`;

  // n8n's built-in fetch — AbortController not available in code-node sandbox,
  // so rely on n8n's per-node timeout (set via options.timeout above in
  // upstream node). 10s is enough for any well-configured MCP server.
  const res = await fetch(endpointUrl, {
    method: 'POST',
    headers,
    body: JSON.stringify(body),
  });
  latencyMs = Date.now() - probeStartedAt;

  if (res.ok) {
    const text = await res.text();
    sampleResponseExcerpt = text.slice(0, 280);
    try {
      const parsed = JSON.parse(text);
      const tools = parsed?.result?.tools;
      if (Array.isArray(tools)) {
        supportedMethods = tools.map((t) => t.name).slice(0, 50);
      }
      ok = true;
    } catch (_) {
      // body wasn't JSON but HTTP OK — degraded but reachable
      ok = true;
    }
  } else {
    ok = false;
    error = `HTTP ${res.status}`;
    sampleResponseExcerpt = (await res.text().catch(() => '')).slice(0, 280);
  }
} catch (err) {
  latencyMs = Date.now() - probeStartedAt;
  ok = false;
  error = `network: ${String(err).slice(0, 200)}`;
}

return [
  {
    json: {
      slug: originalMcp.slug,
      ok,
      latency_ms: latencyMs,
      supported_methods: supportedMethods,
      sample_response_excerpt: sampleResponseExcerpt,
      error,
      transport,
      skip: false,
    },
  },
];
